49	package body en_cl_fix_private_pkg is
50	    
51	    function choose(condition : boolean; if_true : integer; if_false : integer) return integer is
52	    begin
53	        if condition then
54	            return if_true;
55	        end if;
56	        return if_false;
57	    end function;
58	    
59	    function choose(condition : boolean; if_true : std_logic; if_false : std_logic) return std_logic is
60	    begin
61	        if condition then
62	            return if_true;
63	        end if;
64	        return if_false;
65	    end function;
66	    
67	    function to01(x : std_logic) return std_logic is
68	        variable result_v : std_logic;
69	    begin
70	        if x = '1' or x = 'H' then
71	            result_v := '1';
72	        else
73	            result_v := '0';
74	        end if;
75	        return result_v;
76	    end;
77	    
78	    function to01(x : std_logic_vector) return std_logic_vector is
79	        variable result_v : std_logic_vector(x'range);
80	    begin
81	        for i in x'range loop
82	            result_v(i) := to01(x(i));
83	        end loop;
84	        return result_v;
85	    end;
86	    
87	    function toInteger(bool : boolean) return integer is
88	    begin
89	        if bool then
90	            return 1;
91	        else
92	            return 0;
93	        end if;
94	    end;
95	    
96	    function maximum(a, b : integer) return integer is
97	    begin
98	        if a >= b then
99	            return a;
100	        else
101	            return b;
102	        end if;
103	    end;
104	    
105	    function minimum(a, b : integer) return integer is
106	    begin
107	        if a <= b then
108	            return a;
109	        else
110	            return b;
111	        end if;
112	    end;
113	    
114	    function toLower(c : character) return character is
115	        variable v : character;
116	    begin
117	        case c is
118	            when 'A' => v := 'a';
119	            when 'B' => v := 'b';
120	            when 'C' => v := 'c';
121	            when 'D' => v := 'd';
122	            when 'E' => v := 'e';
123	            when 'F' => v := 'f';
124	            when 'G' => v := 'g';
125	            when 'H' => v := 'h';
126	            when 'I' => v := 'i';
127	            when 'J' => v := 'j';
128	            when 'K' => v := 'k';
129	            when 'L' => v := 'l';
130	            when 'M' => v := 'm';
131	            when 'N' => v := 'n';
132	            when 'O' => v := 'o';
133	            when 'P' => v := 'p';
134	            when 'Q' => v := 'q';
135	            when 'R' => v := 'r';
136	            when 'S' => v := 's';
137	            when 'T' => v := 't';
138	            when 'U' => v := 'u';
139	            when 'V' => v := 'v';
140	            when 'W' => v := 'w';
141	            when 'X' => v := 'x';
142	            when 'Y' => v := 'y';
143	            when 'Z' => v := 'z';
144	            when others => v := c;
145	        end case;
146	        return v;
147	    end;
148	    
149	    function toLower(s : string) return string is
150	        variable v : string(s'range);
151	    begin
152	        for i in s'range loop
153	            v(i):= toLower(s(i));
154	        end loop;
155	        return v;
156	    end;
157	    
158	    function string_find_next_match(Str : string; Char : character; StartIdx : natural) return integer is
159	        variable CurrentIdx_v       : integer := StartIdx;
160	        variable Match_v            : boolean := false;
161	        variable MatchIdx_v         : integer := -1;
162	    begin
163	        -- Checks
164	        assert StartIdx <= Str'high and StartIdx >= Str'low report "string_find_next_match: StartIdx out of range" severity Failure;
165	        
166	        -- Implementation
167	        while (not Match_v) and (CurrentIdx_v <= Str'high) loop
168	            if Str(CurrentIdx_v) = Char then
169	                Match_v     := true;
170	                MatchIdx_v  := CurrentIdx_v;
171	            end if;
172	            CurrentIdx_v := CurrentIdx_v + 1;
173	        end loop;
174	        return MatchIdx_v;
175	    end function;
176	    
177	    function string_int_from_char(Char : character) return integer is
178	    begin
179	        case Char is
180	            when '0'    => return 0;
181	            when '1'    => return 1;
182	            when '2'    => return 2;
183	            when '3'    => return 3;
184	            when '4'    => return 4;
185	            when '5'    => return 5;
186	            when '6'    => return 6;
187	            when '7'    => return 7;
188	            when '8'    => return 8;
189	            when '9'    => return 9;
190	            when others => return -1;
191	        end case;
192	        return 0;
193	    end function;
194	    
195	    function string_char_is_numeric(Char : character) return boolean is
196	    begin
197	        return string_int_from_char(Char) /= -1;
198	    end function;
199	    
200	    function string_parse_int(Str : string; StartIdx : natural) return integer is
201	        variable CurrentIdx_v       : integer   := StartIdx;
202	        variable IsNegative_v       : boolean   := false;
203	        variable AbsoluteVal_v      : integer   := 0;
204	    begin
205	        -- Checks
206	        assert StartIdx <= Str'high and StartIdx >= Str'low report "string_parse_int: StartIdx out of range" severity Failure;
207	        
208	        -- Remove leading spaces
209	        while Str(CurrentIdx_v) = ' ' loop
210	            CurrentIdx_v := CurrentIdx_v + 1;
211	        end loop;
212	        
213	        -- Detect negative numbers
214	        if Str(CurrentIdx_v) = '-' then
215	            IsNegative_v := true;
216	            CurrentIdx_v := CurrentIdx_v + 1;
217	        end if;
218	        
219	        -- Parse absolute value
220	        while (CurrentIdx_v <= Str'high) loop
221	            if not string_char_is_numeric(Str(CurrentIdx_v)) then
222	                CurrentIdx_v := Str'high+1;
223	            else
224	                AbsoluteVal_v := AbsoluteVal_v * 10 + string_int_from_char(Str(CurrentIdx_v));
225	                CurrentIdx_v := CurrentIdx_v + 1;
226	            end if;
227	        end loop;
228	        
229	        -- Return number with correct sign
230	        if IsNegative_v then
231	            return -AbsoluteVal_v;
232	        else
233	            return AbsoluteVal_v;
234	        end if;
235	    end function;
236	    
237	end;
