48	-- Architecture
49	---------------------------------------------------------------------------------------------------
50	architecture rtl of cl_fix_add_tb is
51	
52	    constant DataPath_c         : string := tb_path(runner_cfg) & "../bittrue/cosim/cl_fix_add/data/";
53	    
54	    -- Formats
55	    constant AFmt_c             : FixFormatArray_t := cl_fix_read_format_file(DataPath_c & "a_fmt.txt");
56	    constant BFmt_c             : FixFormatArray_t := cl_fix_read_format_file(DataPath_c & "b_fmt.txt");
57	    constant RFmt_c             : FixFormatArray_t := cl_fix_read_format_file(DataPath_c & "r_fmt.txt");
58	    
59	    -- Rounding and saturation modes
60	    constant Rnd_c              : integer_vector := read_file(DataPath_c & "rnd.txt");
61	    constant Sat_c              : integer_vector := read_file(DataPath_c & "sat.txt");
62	    
63	    constant TestCount_c        : positive := AFmt_c'length;
64	    
65	    signal Clk                  : std_logic := '0';
66	    
67	    -- Helper function for printing error info
68	    function Str(x : integer; XFmt : FixFormat_t) return string is
69	    begin
70	        return to_string(cl_fix_to_real(cl_fix_from_integer(x, XFmt), XFmt));
71	    end function;
72	    
73	    procedure Check(i : natural) is
74	        -- Load response data for this test case
75	        constant Expected_c : SlvArray_t := cl_fix_read_file(DataPath_c & "test" & to_string(i) & "_output.txt", RFmt_c(i));
76	        constant Amin       : integer := cl_fix_to_integer(cl_fix_min_value(AFmt_c(i)), AFmt_c(i));
77	        constant Amax       : integer := cl_fix_to_integer(cl_fix_max_value(AFmt_c(i)), AFmt_c(i));
78	        constant Bmin       : integer := cl_fix_to_integer(cl_fix_min_value(BFmt_c(i)), BFmt_c(i));
79	        constant Bmax       : integer := cl_fix_to_integer(cl_fix_max_value(BFmt_c(i)), BFmt_c(i));
80	        variable Idx_v      : natural := 0;
81	        variable Result_v   : std_logic_vector(cl_fix_width(RFmt_c(i))-1 downto 0);
82	    begin
83	        -- The cosim script generates all possible values of both inputs (counters).
84	        -- We repeat the same pattern here.
85	        for b in Bmin to Bmax loop
86	            for a in Amin to Amax loop
87	                -- Calculate result in VHDL
88	                Result_v := cl_fix_add(
89	                    cl_fix_from_integer(a, AFmt_c(i)), AFmt_c(i),
90	                    cl_fix_from_integer(b, BFmt_c(i)), BFmt_c(i),
91	                    RFmt_c(i), FixRound_t'val(Rnd_c(i)), FixSaturate_t'val(Sat_c(i))
92	                );
93	                
94	                -- Check against cosim
95	                if Result_v /= Expected_c(Idx_v) then
96	                    print(
97	                        "Error while calculating " & Str(a, AFmt_c(i)) & " " & to_string(AFmt_c(i)) & " + " & Str(b, BFmt_c(i)) & " " & to_string(BFmt_c(i))
98	                        & " [rnd: " & to_string(FixRound_t'val(Rnd_c(i))) & ", sat: " & to_string(FixSaturate_t'val(Sat_c(i))) & "] --> " & to_string(RFmt_c(i))
99	                    );
100	                    check_equal(Result_v, Expected_c(Idx_v), "Error at index " & to_string(Idx_v));
101	                end if;
102	                Idx_v := Idx_v + 1;
103	                
104	                -- We don't really need a clock, but it avoids iteration limits in the simulator
105	                -- (and avoids confusion for a developer seeing the time stuck at 0 ns).
106	                wait until rising_edge(Clk);
107	            end loop;
108	        end loop;
109	    end procedure;
110	    
111	begin
112	    
113	    test_runner_watchdog(runner, 100 ms);
114	    
115	    Clk <= not Clk after 5 ns;
116	    
117	    ----------------
118	    -- VUnit Main --
119	    ----------------
120	    p_main : process
121	    begin
122	        test_runner_setup(runner, runner_cfg);
123	        
124	        wait until rising_edge(Clk);
125	        
126	        while test_suite loop
127	            if run("test") then
128	                for i in 0 to TestCount_c-1 loop
129	                    Check(i);
130	                end loop;
131	            end if;
132	        end loop;
133	        
134	        print("SUCCESS! All tests passed.");
135	        test_runner_cleanup(runner);
136	    end process;
137	    
138	end rtl;
